<script lang="ts">
	import { Check, Network, Plus, RefreshCw, Save, ShieldCheck } from '@lucide/svelte';
	import FlatSelect from '$lib/components/FlatSelect.svelte';
	import type { DeviceConfig } from '$lib/device-config';

	type FeatureId = 'assets' | 'hybrid-controller' | 'calibration' | 'serial-tcp' | 'network' | 'vpn' | 'alerts' | 'maintenance' | 'account';
	let { id, config }: { id: FeatureId; config: DeviceConfig | null } = $props();
	let product = $derived(config?.device.product ?? 'unified');
	let isRts = $derived(product === 'rts' || product === 'unified');
	let isBms = $derived(product === 'bms' || product === 'unified');
	let notice = $state('');
	let networkMode = $state('DHCP');
	let vpnType = $state('OpenVPN');
	let serialTab = $state('Serial ports');
	let fields = $state<Record<string, string>>({});

	const titles: Record<FeatureId, [string, string]> = {
		assets:['System Info', 'System identity, battery configuration, installation and charging settings.'],
		'hybrid-controller':['Hybrid Controller', 'Power limiting and charge/discharge optimization.'],
		calibration:['Discharge Calibration', 'Battery discharge testing and calibration limits.'],
		'serial-tcp':['Serial & TCP', 'RS‑485 serial ports and Modbus TCP bridges.'],
		network:['Network', 'Ethernet, Wi‑Fi and cellular network configuration.'],
		vpn:['VPN', 'Secure remote connectivity for the energy management system.'],
		alerts:['Email Alerts', 'SMTP delivery, recipients and alarm notification policy.'],
		maintenance:['Maintenance', 'Connectivity diagnostics, device service and safe maintenance actions.'],
		account:['Account', 'Signed-in user profile and credential management.']
	};
	let title = $derived(titles[id]);
	function save(label = 'Settings') { notice = `${label} saved locally. API adapter will submit the profile-specific payload.`; }
	function input(key:string, label:string, type='text', placeholder='') { return { key, label, type, placeholder }; }
	const assetFields = [input('owner','Asset owner'),input('site','Site / project'),input('address','Installation address'),input('maxicomSerial','MAXiCom serial number'),input('commissionedAt','Commissioning date','date')];
	const calibrationFields = [input('targetVoltage','Target voltage (V)','number'),input('dischargeCurrent','Discharge current (A)','number'),input('duration','Maximum duration (min)','number'),input('cutoffVoltage','Cutoff voltage (V)','number'),input('temperatureLimit','Temperature limit (°C)','number')];
	const hybridFields = [input('maxActivePower','Maximum active power (kW)','number'),input('minSoc','Minimum SoC (%)','number'),input('maxSoc','Maximum SoC (%)','number'),input('chargePower','Maximum charge power (kW)','number'),input('dischargePower','Maximum discharge power (kW)','number')];
	const smtpFields = [input('host','SMTP host'),input('port','SMTP port','number'),input('username','SMTP username'),input('password','SMTP password','password'),input('senderAddress','Sender address','email'),input('recipients','Recipients (comma separated)')];
	const accountFields = [input('displayName','Display name'),input('username','Username'),input('currentPassword','Current password','password'),input('newPassword','New password','password'),input('confirmPassword','Confirm new password','password')];
</script>

<section class="workspace-page">
	<div class="page-title"><div><h2>{title[0]}</h2><p>{title[1]}</p></div>{#if id !== 'maintenance'}<button class="primary" type="button" onclick={() => save(title[0])}><Save size={17} /> Save changes</button>{/if}</div>
	{#if notice}<div class="notice"><Check size={16} />{notice}</div>{/if}

	{#if id === 'assets'}<section class="panel"><h3>Asset identity</h3><div class="form-grid">{#each assetFields as field}<label>{field.label}<input type={field.type} placeholder={field.placeholder} bind:value={fields[field.key]} /></label>{/each}</div><div class="divider"></div><h3>Battery test history</h3><p class="muted">Saved discharge tests will appear here when the BMS API is connected.</p></section>{/if}
	{#if id === 'calibration'}<section class="panel"><h3>Discharge test profile</h3><div class="form-grid">{#each calibrationFields as field}<label>{field.label}<input type={field.type} bind:value={fields[field.key]} /></label>{/each}</div><p class="hint">BMS API: <code>bms.tools.discharge.getConfig</code> and <code>bms.tools.discharge.saveConfig</code>.</p></section>{/if}
	{#if id === 'hybrid-controller'}<section class="panel"><h3>Optimization policy</h3><div class="form-grid"><label>Operating mode<FlatSelect bind:value={fields.mode} options={['EVN Control','Self-consumption','Peak shaving','Manual']} placeholder="Select a mode" /></label>{#each hybridFields as field}<label>{field.label}<input type={field.type} bind:value={fields[field.key]} /></label>{/each}</div><p class="hint">This section is RTS-only and controls power limitation, charge and discharge optimization.</p></section>{/if}
	{#if id === 'serial-tcp'}<div class="tabs"><button class:active={serialTab === 'Serial ports'} type="button" onclick={() => serialTab='Serial ports'}>Serial ports</button>{#if config?.connectivity.tcp}<button class:active={serialTab === 'TCP bridges'} type="button" onclick={() => serialTab='TCP bridges'}>TCP bridges</button>{/if}</div><section class="panel"><div class="panel-heading"><div><h3>{serialTab}</h3><p>{serialTab === 'Serial ports' ? 'Bridge.Modbus.Serial / RS‑485' : 'Bridge.Modbus.Tcp'}</p></div><button class="secondary" type="button"><Plus size={16} /> Add {serialTab === 'Serial ports' ? 'serial port' : 'TCP bridge'}</button></div>{#if serialTab === 'Serial ports'}<div class="form-grid"><label>Alias<input bind:value={fields.serialAlias} placeholder="e.g. Battery RS‑485" /></label><label>Device path<input bind:value={fields.devicePath} placeholder="e.g. /dev/ttyS1" /></label><label>Baud rate<FlatSelect bind:value={fields.baudRate} options={['9600','19200','38400','57600','115200']} placeholder="Select baud rate" /></label><label>Data bits<FlatSelect bind:value={fields.dataBits} options={['7','8']} placeholder="Select data bits" /></label><label>Parity<FlatSelect bind:value={fields.parity} options={['NONE','EVEN','ODD']} placeholder="Select parity" /></label><label>Stop bits<FlatSelect bind:value={fields.stopBits} options={['1','2']} placeholder="Select stop bits" /></label></div>{:else}<div class="form-grid"><label>Display name<input bind:value={fields.tcpAlias} placeholder="e.g. Factory TCP gateway" /></label><label>Host / IP address<input bind:value={fields.tcpHost} placeholder="e.g. 192.168.1.10" /></label><label>TCP port<input type="number" bind:value={fields.tcpPort} placeholder="502" /></label><label>Modbus ID<input bind:value={fields.tcpId} placeholder="e.g. modbus3" /></label></div>{/if}</section>{/if}
	{#if id === 'network'}<div class="tabs"><button class:active={networkMode === 'DHCP' || networkMode === 'Static'} type="button" onclick={() => networkMode='DHCP'}>Ethernet</button><button class:active={networkMode === 'Wi‑Fi'} type="button" onclick={() => networkMode='Wi‑Fi'}>Wi‑Fi</button>{#if isRts}<button class:active={networkMode === '4G/LTE'} type="button" onclick={() => networkMode='4G/LTE'}>4G / LTE</button>{/if}</div><section class="panel">{#if networkMode === 'Wi‑Fi'}<h3>Wi‑Fi client</h3><div class="form-grid"><label>SSID<input bind:value={fields.ssid} /></label><label>Security<FlatSelect bind:value={fields.wifiSecurity} options={['WPA2-PSK','WPA3-PSK','Open']} placeholder="Select security" /></label><label>Password<input type="password" bind:value={fields.wifiPassword} /></label></div>{:else if networkMode === '4G/LTE'}<h3>4G / LTE modem</h3><div class="form-grid"><label>APN<input bind:value={fields.apn} placeholder="Carrier APN" /></label><label>PIN<input type="password" bind:value={fields.simPin} /></label><label>Username<input bind:value={fields.cellularUser} /></label><label>Password<input type="password" bind:value={fields.cellularPassword} /></label></div>{:else}<h3>Ethernet</h3><div class="form-grid"><label>Address assignment<FlatSelect bind:value={networkMode} options={['DHCP','Static']} /></label>{#if networkMode === 'Static'}<label>IPv4 address<input bind:value={fields.ipv4} /></label><label>Prefix length<input type="number" bind:value={fields.prefix} placeholder="24" /></label><label>Gateway<input bind:value={fields.gateway} /></label><label>DNS server<input bind:value={fields.dns} /></label>{/if}</div>{/if}</section>{/if}
	{#if id === 'vpn'}<div class="tabs"><button class:active={vpnType==='OpenVPN'} type="button" onclick={() => vpnType='OpenVPN'}>OpenVPN</button><button class:active={vpnType==='IPsec'} type="button" onclick={() => vpnType='IPsec'}>IPsec</button></div><section class="panel"><h3>{vpnType} connection</h3>{#if vpnType==='OpenVPN'}<div class="form-grid"><label>Profile name<input bind:value={fields.ovpnName} /></label><label>Server address<input bind:value={fields.ovpnServer} /></label><label>Port<input type="number" bind:value={fields.ovpnPort} /></label><label>Configuration file<input type="file" /></label></div>{:else}<div class="form-grid"><label>VPN alias<input bind:value={fields.ipsecAlias} /></label><label>Remote gateway<input bind:value={fields.gateway} /></label><label>Local subnet<input bind:value={fields.localSubnet} /></label><label>Remote subnet<input bind:value={fields.remoteSubnet} /></label><label>Pre-shared key<input type="password" bind:value={fields.psk} /></label></div>{/if}</section>{/if}
	{#if id === 'alerts'}<section class="panel"><h3>SMTP delivery</h3><div class="form-grid">{#each smtpFields as field}<label>{field.label}<input type={field.type} bind:value={fields[field.key]} /></label>{/each}<label>Security<FlatSelect bind:value={fields.security} options={['plain','STARTTLS','SSL/TLS']} placeholder="Select security" /></label><label>Reminder interval (minutes)<input type="number" bind:value={fields.reminderMinutes} /></label></div><div class="divider"></div><h3>Notification policy</h3><div class="checks"><label><input type="checkbox" /> Communication alerts</label><label><input type="checkbox" /> Battery alerts</label><label><input type="checkbox" /> Recovery notification</label></div></section>{/if}
	{#if id === 'maintenance'}<section class="panel"><h3>Service actions</h3><div class="actions"><button class="secondary" type="button" onclick={() => notice='Wi‑Fi scan requested.'}><Network size={17} /> Scan Wi‑Fi</button><button class="secondary" type="button" onclick={() => notice='System diagnostics requested.'}><RefreshCw size={17} /> Run diagnostics</button><button class="danger" type="button" onclick={() => notice='Restart confirmation is required before calling the device API.'}>Restart device</button></div><p class="hint">Maintenance commands are intentionally protected; the final adapter will require confirmation before calling the BMS maintenance RPC or RTS service action.</p></section>{/if}
	{#if id === 'account'}<section class="panel"><h3>Profile & credentials</h3><div class="form-grid">{#each accountFields as field}<label>{field.label}<input type={field.type} bind:value={fields[field.key]} /></label>{/each}</div></section>{/if}
</section>

<style>
	.workspace-page { animation:enter .18s ease-out; }.page-title { display:flex; justify-content:space-between; align-items:flex-start; gap:18px; margin-bottom:25px; }.page-title h2 { margin:0; color:#172b4d; font-size:24px; font-weight:500; }.page-title p { margin:7px 0 0; color:#718096; font-size:16px; }.primary,.secondary,.danger { display:inline-flex; align-items:center; justify-content:center; gap:8px; min-height:39px; padding:0 14px; border:1px solid transparent; border-radius:8px; cursor:pointer; font:inherit; font-size:14px; }.primary { color:#fff; background:#1749ad; }.secondary { border-color:#d8e1ef; color:#38506f; background:#fff; }.danger { border-color:#f3d2cf; color:#c72b21; background:#fff8f7; }.panel { padding:20px; border:1px solid #e1e7f0; border-radius:12px; background:#fff; }.panel h3 { margin:0 0 15px; color:#31415c; font-size:16px; font-weight:500; }.panel-heading { display:flex; align-items:start; justify-content:space-between; gap:15px; margin-bottom:17px; }.panel-heading h3 { margin-bottom:4px; }.panel-heading p,.muted { margin:0; color:#7c889a; font-size:13px; }.form-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:14px 17px; }label { display:grid; gap:6px; color:#536078; font-size:13px; }input { width:100%; height:39px; padding:0 11px; border:1px solid #d7dfeb; border-radius:7px; color:#273853; background:#fff; font:inherit; font-size:14px; }input:focus { outline:0; border-color:#3764c0; box-shadow:0 0 0 3px rgba(55,100,192,.12); }.divider { height:1px; margin:21px 0; background:#edf0f5; }.hint { margin:18px 0 0; color:#748198; font-size:13px; }.hint code { color:#345999; }.tabs { display:flex; gap:6px; margin-bottom:15px; border-bottom:1px solid #e2e8f1; }.tabs button { min-height:37px; padding:0 13px; border:0; border-bottom:2px solid transparent; color:#65738b; background:transparent; cursor:pointer; font:inherit; font-size:14px; }.tabs button.active { border-color:#2454b6; color:#1d4ba7; font-weight:500; }.checks,.actions { display:flex; flex-wrap:wrap; gap:11px 18px; }.checks label { display:flex; align-items:center; gap:7px; cursor:pointer; }.checks input { width:16px; height:16px; accent-color:#1749ad; }.notice { display:flex; align-items:center; gap:7px; margin:-10px 0 15px; padding:10px 12px; border:1px solid #cae7d5; border-radius:8px; color:#28784e; background:#f2fbf5; font-size:14px; }@keyframes enter { from { opacity:0; transform:translateY(4px); } to { opacity:1; transform:translateY(0); } }@media (max-width:900px) { .panel { padding:18px; }.page-title { flex-direction:column; }.form-grid { grid-template-columns:1fr; } }@media (max-width:620px) { .page-title p { font-size:15px; }.panel-heading { flex-direction:column; }.panel-heading .secondary { width:100%; }.tabs { overflow-x:auto; } }
</style>
